async function compressAdminProfilePhoto(file){const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(new Error('Invalid image file'));el.src=raw});const scale=Math.min(1,900/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Image compression is unavailable.');ctx.drawImage(img,0,0,canvas.width,canvas.height);let out=canvas.toDataURL('image/webp',0.72);if(out.length>900000)out=canvas.toDataURL('image/webp',0.5);if(out.length>1200000)throw new Error('Photo is too large after compression. Choose another image.');return out}
async function compressProductImage(file){const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(new Error('Invalid image file'));el.src=raw});const scale=Math.min(1,1500/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let out=canvas.toDataURL('image/webp',0.7);if(out.length>700000)out=canvas.toDataURL('image/webp',0.52);if(out.length>850000)throw new Error('Image is too large after compression. Choose a smaller photo.');return out}
async function compressBrandIcon(file){const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(new Error('Invalid image file'));el.src=raw});const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Image processing is unavailable.');ctx.clearRect(0,0,512,512);const scale=Math.min(440/img.width,440/img.height);const width=Math.max(1,Math.round(img.width*scale)),height=Math.max(1,Math.round(img.height*scale));ctx.drawImage(img,(512-width)/2,(512-height)/2,width,height);let output=canvas.toDataURL('image/webp',0.82);if(output.length>900000)output=canvas.toDataURL('image/webp',0.62);if(output.length>1200000)throw new Error('Icon file is too large after compression. Choose another image.');return output}
async function compressStoreLogo(file){const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(new Error('Invalid image file'));el.src=raw});const scale=Math.min(1,900/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Image processing is unavailable.');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let output=canvas.toDataURL('image/webp',0.78);if(output.length>900000)output=canvas.toDataURL('image/webp',0.58);if(output.length>1200000)throw new Error('Logo file is too large after compression. Choose a smaller image.');return output}
