 useEffect(()=>{load()},[])
 function edit(p){setUploadError('');setEditing(p._id);setForm({name:p.name||'',sku:p.sku||'',price:String(p.price??''),compareAtPrice:String(p.compareAtPrice??''),stock:String(p.stock??0),variantStocks:(p.variantStocks||[]).map(v=>[v.size,v.color,v.stock].join(' | ')).join('\n'),description:p.description||'',category:p.category?._id||'',sizes:(p.sizes||[]).join(', '),colors:(p.colors||[]).join(', '),images:p.images||[],tags:(p.tags||[]).join(', '),isPublished:!!p.isPublished,isFeatured:!!p.isFeatured,isBestSeller:!!p.isBestSeller});setShow(true);setNotice('')}
