 async function uploadImages(files){const selected=Array.from(files||[]);if(!selected.length)return;if(form.images.length+selected.length>8){setUploadError('You can add up to 8 images per product.');return}setUploading(true);setUploadError('');try{const cloud=import.meta.env.VITE_CLOUDINARY_CLOUD_NAME,preset=import.meta.env.VITE_CLOUDINARY_UPLOAD_PRESET,added=[];for(const file of selected){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw new Error('Use JPG, PNG, WEBP or GIF images.');if(file.size>8*1024*1024)throw new Error('Each image must be 8 MB or smaller.');let stored='';if(cloud&&preset){try{const body=new FormData();body.append('file',file);body.append('upload_preset',preset);body.append('folder','smart-outfit/products');const res=await fetch('https://api.cloudinary.com/v1_1/'+cloud+'/image/upload',{method:'POST',body});const data=await res.json();if(!res.ok||!data.secure_url)throw new Error(data.error?.message||'Cloud image upload failed.');stored=data.secure_url}catch(err){stored=await compressProductImage(file)}}else stored=await compressProductImage(file);added.push(stored)}const total=[...form.images,...added].reduce((n,x)=>n+String(x).length,0);if(total>5200000)throw new Error('Combined compressed images exceed 5 MB. Upload fewer images or configure a working Cloudinary account.');setForm(f=>({...f,images:[...f.images,...added].slice(0,8)}));if(added.some(x=>x.startsWith('data:image/')))setUploadError('Image added with compressed database storage. Configure Cloudinary for permanent CDN hosting.')}catch(e){setUploadError(e.message||'Image upload failed.')}finally{setUploading(false)}}
